Here is the commit message:
core: fix INFO() and ERROR() macros in core/serial_ftdi.cpp

Error introduced in da7ea17b66: the INFO() and ERROR() macros
pass stdout instead of the format string as first parameter
to report_error(). Ooooops. How did this ever pass the
compile tests!?

Signed-off-by: Berthold Stoeger <bstoeger@mail.tuwien.ac.at>

Here is the root cause:
The bug was caused by the `INFO()` and `ERROR()` macros incorrectly passing `stderr` as the first parameter to the `report_info()` function instead of the format string. This misconfiguration led to improper logging behavior, as the intended message format was not being utilized correctly, which could result in misleading or incomplete log entries.

Here is the patch:

 #include "errorhelper.h"
-#define INFO(context, fmt, ...)	report_info(stderr, "INFO: " fmt, ##__VA_ARGS__)
-#define ERROR(context, fmt, ...)	report_info(stderr, "ERROR: " fmt, ##__VA_ARGS__)
+#define INFO(context, fmt, ...)	report_info("INFO: " fmt, ##__VA_ARGS__)
+#define ERROR(context, fmt, ...)	report_info("ERROR: " fmt, ##__VA_ARGS__)
 //#define SYSERROR(context, errcode)	ERROR(__FILE__ ":" __LINE__ ": %s", strerror(errcode))
 #define SYSERROR(context, errcode)	;

 static dc_status_t serial_ftdi_purge (void *io, dc_direction_t queue)
 {
 	ftdi_serial_t *device = io;

 	if (device == NULL)
 		return DC_STATUS_INVALIDARGS;

 	size_t input;
 	serial_ftdi_get_available (io, &input);
-	INFO (device->context, "Flush: queue=%u, input=%lu, output=%i", queue, input,
+	INFO (device->context, "Flush: queue=%u, input=%lu, output=%i", queue, (unsigned long)input,
 	      serial_ftdi_get_transmitted (device));

 	switch (queue) {
 	case DC_DIRECTION_INPUT:  /**< Input direction */
 		if (ftdi_usb_purge_tx_buffer(device->ftdi_ctx)) {
 			ERROR (device->context, "%s", ftdi_get_error_string(device->ftdi_ctx));
 			return DC_STATUS_IO;
 		}
 		break;
 	case DC_DIRECTION_OUTPUT: /**< Output direction */
 		if (ftdi_usb_purge_rx_buffer(device->ftdi_ctx)) {
 			ERROR (device->context, "%s", ftdi_get_error_string(device->ftdi_ctx));
 			return DC_STATUS_IO;
 		}
 		break;
 	case DC_DIRECTION_ALL: /**< All directions */
 	default:
 		if (ftdi_usb_reset(device->ftdi_ctx)) {
 			ERROR (device->context, "%s", ftdi_get_error_string(device->ftdi_ctx));
 			return DC_STATUS_IO;
 		}
 		break;
 	}

 	return DC_STATUS_SUCCESS;
 }



